    12	  const place = (x0: number, x1: number, near: number, beach: boolean) => {
    13	    const step = 36;
    14	    for (let gx = x0; gx < x1; gx += step) for (let gz = -1800; gz < 1800; gz += step) {
    15	      const ix = Math.round(gx / step), iz = Math.round(gz / step);
    16	      if (ix % 5 === 0 || iz % 5 === 0) continue;  // chừa đường phố
    17	      if (avoid(gx, gz) || rand() < 0.16) continue;
    18	      const nearR = 1 - clamp((Math.abs(gx - near)) / 900, 0, 1);
    19	      let h = 9 + rand() * 26 + nearR * rand() * 65 + (rand() < 0.05 ? 55 : 0);
    20	      if (beach && gx > 1290) h = 45 + rand() * 115; // khách sạn ven biển Mỹ Khê
    21	      items.push({ x: gx + (rand() - 0.5) * 6, z: gz + (rand() - 0.5) * 6, w: 14 + rand() * 15, d: 14 + rand() * 15, h, c: palette[Math.floor(rand() * palette.length)] });
    22	    }
    23	  };
    24	  place(-2000, -330, -330, false); // bờ Tây — trung tâm Hải Châu
    25	  place(340, 1450, 340, true);      // bờ Đông — Sơn Trà
    26	  // Gom thành cụm, mỗi cụm là một LOD (gần: có cửa sổ; xa: khối trơn)
    27	  const cell = 900, clusters = new Map<string, typeof items>();
    28	  for (const b of items) { const key = `${Math.floor(b.x / cell)}_${Math.floor(b.z / cell)}`; if (!clusters.has(key)) clusters.set(key, []); clusters.get(key).push(b); }
