     8	
     9	/* ============================ Đường phố ============================
    10	   Mặt đường được gom chung (cả mặt Cầu Rồng) để giảm draw call: ROADS3 = 3 làn/chiều, ROADS2 = 2 làn/chiều */
    11	export const ROADS3: THREE.BufferGeometry[] = [], ROADS2: THREE.BufferGeometry[] = [];
    12	const MEDIANS: THREE.BufferGeometry[] = [];
    13	
    14	export function buildStreets() {
    15	  const y = CONFIG.roadY + 0.03, med = CONFIG.median / 2, car = CONFIG.lanesPerDir * CONFIG.laneWidth + CONFIG.shoulder;
    16	  // Trục cầu nối dài trên bờ: Nguyễn Văn Linh (Tây) – Võ Văn Kiệt (Đông)
    17	  for (const [x0, x1] of [[-1900, -333], [333, 1480]]) {
    18	    const len = x1 - x0, xc = (x0 + x1) / 2;
    19	    ROADS3.push(bentPlane(len, car, xc, 0.03, med + car / 2, 1, flatY));
    20	    ROADS3.push(bentPlane(len, car, xc, 0.03, -(med + car / 2), 1, flatY, true));
    21	    const mb = new THREE.BoxGeometry(len, 0.3, CONFIG.median); mb.translate(xc, CONFIG.roadY + 0.15, 0); MEDIANS.push(mb);
    22	    const sw = new THREE.BoxGeometry(len, 0.2, 3); for (const s of [-1, 1]) { const g = sw.clone(); g.translate(xc, CONFIG.roadY + 0.1, s * 18.2); MEDIANS.push(g); }
    23	  }
    24	  // Đường ven sông: Bạch Đằng (Tây), Trần Hưng Đạo (Đông) — 2 làn mỗi chiều
    25	  for (const [xc, z0, z1] of [[-299, -2600, 2600], [299, -2300, 2600]]) {
    26	    const len = z1 - z0, zc = (z0 + z1) / 2;
    27	    ROADS2.push(zPlane(len, 9, xc + 6, y - 0.01, zc, false));
    28	    ROADS2.push(zPlane(len, 9, xc - 6, y - 0.01, zc, true));
    29	    const mb = new THREE.BoxGeometry(3, 0.3, len); mb.translate(xc, CONFIG.roadY + 0.15, zc); MEDIANS.push(mb);
    30	  }
    31	}
    32	export function finalizeRoads() {
    33	  const tex3 = MAT.road.map, tex2 = MAT.road2.map;
    34	  tex3.repeat.set(1, 1); tex2.repeat.set(1, 1);
    35	  // Chuẩn hoá UV theo mét để vạch kẻ đều (chu kỳ 12 m)
    36	  const fixUV = (g: THREE.BufferGeometry) => {
    37	    const p = g.attributes.position, uv = g.attributes.uv;
    38	    const along = (p.getX(1) - p.getX(0)) !== 0 && Math.abs(p.getZ(1) - p.getZ(0)) < 1e-3 ? 'x' : 'z';
    39	    for (let i = 0; i < uv.count; i++) uv.setX(i, (along === 'x' ? p.getX(i) : p.getZ(i)) / 12);
    40	    uv.needsUpdate = true; return g;
    41	  };
    42	  scene.add(shadowed(new THREE.Mesh(mergeGeometries(ROADS3.map(fixUV)), MAT.road), false, true));
    43	  scene.add(shadowed(new THREE.Mesh(mergeGeometries(ROADS2.map(fixUV)), MAT.road2), false, true));
    44	  scene.add(shadowed(new THREE.Mesh(mergeGeometries(MEDIANS), MAT.grass), false, true));
    45	}
