     9	let shLut: number[][] = null;
    10	export function shRoadY(x: number) {
    11	  if (Math.abs(x) <= SH.fixedStart) return SH.deckY;                   // nhịp quay phẳng tuyệt đối
    12	  const P = SH.roadProfile;
    13	  if (x <= P[0][0] || x >= P[P.length - 1][0]) return CONFIG.roadY;
    14	  if (!shLut) {
    15	    const c = new THREE.CatmullRomCurve3(P.map(([a, b]) => new THREE.Vector3(a, b, 0)), false, 'centripetal');
    16	    shLut = c.getPoints(3000).map((v) => [v.x, v.y]).sort((a, b) => a[0] - b[0]);
    17	  }
    18	  let lo = 0, hi = shLut.length - 1;
    19	  while (hi - lo > 1) { const mid = (lo + hi) >> 1; if (shLut[mid][0] < x) lo = mid; else hi = mid; }
    20	  const [x0, y0] = shLut[lo], [x1, y1] = shLut[hi];
    21	  return Math.max(CONFIG.roadY, lerp(y0, y1, (x - x0) / Math.max(1e-6, x1 - x0)));
    22	}
    23	export const shFlat = () => SH.deckY;
=== thuan-phuoc/profile.ts
     1	import { CONFIG } from '../../config';
     2	import { lerp, clamp } from '../../common/math';
     3	
     4	/* [config] Cầu Thuận Phước: thông số ở CONFIG.thuanPhuoc; mọi kích thước tính bằng mét.
     5	   Gốc tọa độ cục bộ: tim cầu; group dời tới z = CONFIG.thuanPhuoc.z. */
     6	export const TP = CONFIG.thuanPhuoc;
     7	
     8	/* Cao độ mặt đường theo x: vồng parabol trên phần cầu treo, hạ dần qua 12 nhịp dẫn
     9	   (đường cong Hermite liền dốc, dốc ≤ ~4%), rồi đường đắp về mặt đất. */
    10	export function tpRoadY(x: number) {
    11	  const ax = Math.abs(x), A = TP.anchorX, E = TP.endX, R = TP.embankment;
    12	  const pE = CONFIG.roadY + TP.abutmentRise, gE = -TP.abutmentRise / R; // dốc tại mố
    13	  const herm = (t: number, p0: number, m0: number, p1: number, m1: number) => {
    14	    const t2 = t * t, t3 = t2 * t;
    15	    return (2 * t3 - 3 * t2 + 1) * p0 + (t3 - 2 * t2 + t) * m0 + (-2 * t3 + 3 * t2) * p1 + (t3 - t2) * m1;
    16	  };
    17	  if (ax <= A) return TP.roadCenterY - (TP.roadCenterY - TP.roadAnchorY) * (ax / A) ** 2;
    18	  if (ax <= E) {
    19	    const L = E - A, m0 = -2 * (TP.roadCenterY - TP.roadAnchorY) / A * L;
    20	    return herm((ax - A) / L, TP.roadAnchorY, m0, pE, gE * L);
    21	  }
    22	  if (ax <= E + R) return herm((ax - E) / R, pE, gE * R, CONFIG.roadY, 0);
    23	  return CONFIG.roadY;
    24	}
    25	/* Cao độ tim cáp chủ: parabol y = y_top − 4f·u(1 − u) */
    26	export function tpCableY(x: number) {
    27	  const ax = Math.abs(x);
    28	  if (ax <= TP.towerX) { const u = (x + TP.towerX) / TP.mainSpan; return TP.saddleY - 4 * TP.sag * u * (1 - u); }
    29	  const t = clamp((ax - TP.towerX) / (TP.cableAnchorX - TP.towerX), 0, 1);
    30	  return lerp(TP.saddleY, TP.anchorCableY, t) - 4 * TP.sideSag * t * (1 - t);
    31	}
    32	/* Vị trí hanger theo x (một mặt phẳng cáp) */
    33	export function tpHangerStations() {
    34	  const out: { x: number; special: boolean }[] = [], nM = TP.hangersMain, dM = TP.mainSpan / (nM + 1), dS = TP.sideSpan / (TP.hangersSide + 1);
    35	  for (let i = 0; i < nM; i++) out.push({ x: -TP.towerX + (i + 1) * dM, special: i < 2 || i >= nM - 2 || i === (nM - 1) / 2 });
    36	  for (const s of [-1, 1]) for (let i = 0; i < TP.hangersSide; i++) {
    37	    out.push({ x: s * (TP.towerX + (i + 1) * dS), special: i === 0 || i === TP.hangersSide - 1 });
    38	  }
    39	  return out;
    40	}
