    10	let ttlLut: number[][] = null;
    11	export function ttlRoadY(x: number) {
    12	  const P = TTL.roadProfile;
    13	  if (x <= P[0][0] || x >= P[P.length - 1][0]) return CONFIG.roadY;
    14	  if (!ttlLut) {
    15	    const c = new THREE.CatmullRomCurve3(P.map(([a, b]) => new THREE.Vector3(a, b, 0)), false, 'centripetal');
    16	    ttlLut = c.getPoints(4000).map((v) => [v.x, v.y]).sort((a, b) => a[0] - b[0]);
    17	  }
