    19	  while (hi - lo > 1) { const mid = (lo + hi) >> 1; if (ttlLut[mid][0] < x) lo = mid; else hi = mid; }
    20	  const [x0, y0] = ttlLut[lo], [x1, y1] = ttlLut[hi];
