    25	export function ttlPylonSection(t: number) {
    26	  const Lx = TTL.pylonLen[1] + (TTL.pylonLen[0] - TTL.pylonLen[1]) * Math.pow(1 - t, 1.4) + 2.4 * Math.sin(Math.PI * t) * (1 - t);
