    10	/* Thời gian thật từng giai đoạn (giây), chia cho hệ số tăng tốc */
    11	const DUR: Record<Exclude<ImState, 'IDLE'>, number> = { FLOAT_IN: 70, POSITION: 45, BALLAST: 100, PULL_JOINT: 40, BACKFILL: 70, DONE: 15 };
