    14	
    15	export class ImmersionController extends EventTarget {
    16	  state: ImState = 'IDLE';
    17	  t = 0;
    18	  speed = 10;
    19	  /* đầu ra, vị trí đốt 3 so với vị trí hoàn thiện */
    20	  zOff = 0; lift = 0; gap = 0;
    21	  fill = 1;        // 0 → 1: mức lấp đá hộc phủ nóc
    22	  tugs = 0;        // 0: đang kéo; 1: tàu kéo đã rút về
    23	  jack = 0;        // 0 → 1: kích kéo đang co
    24	  fromTour = false;
    25	  get busy() { return this.state !== 'IDLE'; }
    26	  start(speed?: number) {
    27	    if (this.state !== 'IDLE') return false;
    28	    if (speed) this.speed = speed;
    29	    this.go('FLOAT_IN'); this.dispatchEvent(new Event('immerseStart'));
