    59	        if (k >= 1) this.go('BACKFILL');
    60	        break;
    61	      case 'BACKFILL':
    62	        this.lift = 0; this.gap = 0; this.jack = 0; this.fill = smooth(k);
    63	        if (k >= 1) this.go('DONE');
    64	        break;
    65	      case 'DONE':
