    10	export interface Riverbed { group: THREE.Group; ribbons: THREE.Mesh[] }
    11	export function hrBuildRiverbed(M: HrMaterials): Riverbed {
    12	  const group = new THREE.Group(); group.name = 'hr-riverbed';
    13	  // lưới đáy sông: mỗi hàng ngang x có 6 cột z: biên, mép miệng hào, chân hào (×2)
