    34	      const x = lo + (hi - lo) * k / n, y = hrBedY(x) + 0.04, w = hrTrenchTop(x);
    35	      p.push(x, y, -w, x, y, w); uv.push(x / 8, -w / 8, x / 8, w / 8);
