  add('shSwing', -SH.fixedStart, SH.fixedStart, SHZ - shH, SHZ + shH, stSongHanY, ST_GATE_SWING);
  add('songHanW', -SH_X, -SH.fixedStart, SHZ - shH, SHZ + shH, stSongHanY);
  add('songHanE', SH.fixedStart, SH_X, SHZ - shH, SHZ + shH, stSongHanY);
  /* Cầu Rồng: cả bề rộng giữa hai lan can */
  const drH = DR_RAIL_IN - R;                                       // 18,23
  add('dragon', -DR_X, DR_X, -drH, drH, stDragonY);
  /* Cầu Tình Yêu: kéo vào bờ qua khe lan can kè (promenade.ts bỏ lan can ở |z − love.z| < width/2 + railGap); lối vào duy nhất là cạnh x = BANK_IN chung với vùng bờ Đông
  add('love', LV_X0 + R, BANK_IN, LV.z - (LV_IN - R), LV.z + (LV_IN - R), stLoveY);
  /* đầu cầu trên bờ: đường nối dài, cùng cao độ với vùng bờ */
  for (const [id, s] of [['dragonW', -1], ['dragonE', 1]] as [string, number][]) {
    add(id, s < 0 ? BX.x0 : DR_X, s < 0 ? -DR_X : BX.x1, -AX_SIDE.z1, AX_SIDE.z1, stBankY);
  }
  for (const [id, s] of [['shLandW', -1], ['shLandE', 1]] as [string, number][]) {
    add(id, s < 0 ? BX.x0 : SH_X, s < 0 ? -SH_X : BX.x1, SHZ - SH_LAND_HALF, SHZ + SH_LAND_HALF, stBankY);
  }
  /* hai bờ: từ lan can kè lùi radius (cả chỗ không có lan can ở chân cầu: vùng bờ đã cắt quanh cầu) ra tới hết khung; cắt quanh thân Cầu Rồng (|z| < 19,35) và th
  const drCut = DR_EDGE + R, shCut = SH_ABUT + R;
  for (const [id, s] of [['bankW', -1], ['bankE', 1]] as [string, number][]) {
    const x0 = s < 0 ? BX.x0 : BANK_IN, x1 = s < 0 ? -BANK_IN : BX.x1;
    add(id, x0, x1, BX.z0, SHZ - shCut, stBankY);
    add(id, x0, x1, SHZ + shCut, -drCut, stBankY);
    add(id, x0, x1, drCut, BX.z1, stBankY);
  }
  return zs;
}

/* ===== Đường tim thân rồng: chép điểm điều khiển body.ts:27-38 và CatmullRomCurve3 centripetal của three (không import three) ===== */
export function stSpinePoints(): [number, number][] {
/* ============================ Đi dạo: vật cản thu từ cảnh đã dựng ============================
   Gọi MỘT lần, lần đầu vào chế độ (sau khi mọi bước dọn nhà đã chạy): chỉ đọc cảnh, không đụng chuỗi rand() hay thứ tự dựng (spec §6).
   - Nhà đang hiện (collectBuildings: level gần của THREE.LOD, bỏ instance scale 0) có chân đế chạm khung CONFIG.stroll.bounds: chữ nhật thẳng trục (nhà không xoay, city.ts)
   - Chân đế địa danh và pano ven sông (riverfront footprints), trừ chân đế có tâm trong vùng `love`: Cầu Tình Yêu đi được, lan can / tượng đã dựng riêng ở mapData
   Vật cản hỏng (số không hữu hạn, rộng ≤ 0) thì bỏ và đếm: lõi bản đồ không lập chỉ mục được nhưng stSegClear vẫn thấy, nên không được lọt vào. 
import { CONFIG } from '../../config';
import { collectBuildings, type Rect } from '../../environment/riverfront/clearance';
import { getRiverfront } from '../../environment/riverfront';
import { stAddSolids, type StMap, type StSolid } from './map';

export const stSceneStats = { buildings: 0, footprints: 0, skipped: 0 };

const stGood = (r: Rect): boolean => Number.isFinite(r.x0) && Number.isFinite(r.x1) && Number.isFinite(r.z0) && Number.isFinite(r.z1) && r.x1 > r.x0 && r.z1 > r.z0;

export function stCollectRuntime(map: StMap): number {
  const B = CONFIG.stroll.bounds, out: StSolid[] = [];
  let nb = 0, nf = 0, bad = 0;
  for (const b of collectBuildings()) {
    const r = { x0: b.x - b.w / 2, x1: b.x + b.w / 2, z0: b.z - b.d / 2, z1: b.z + b.d / 2 };
    if (!stGood(r)) { bad++; continue; }
    if (r.x1 < B.x0 || r.x0 > B.x1 || r.z1 < B.z0 || r.z0 > B.z1) continue;
    out.push({ kind: 'rect', ...r }); nb++;
  }
  const love = map.zones.find((z) => z.id === 'love');
  for (const f of getRiverfront()?.footprints ?? []) {
    if (!stGood(f)) { bad++; continue; }
    const cx = (f.x0 + f.x1) / 2, cz = (f.z0 + f.z1) / 2;
    if (love && cx >= love.x0 && cx <= love.x1 && cz >= love.z0 && cz <= love.z1) continue;
    out.push({ kind: 'rect', x0: f.x0, x1: f.x1, z0: f.z0, z1: f.z1 }); nf++;
  }
  if (bad) console.warn(`[stroll] bỏ ${bad} vật cản hỏng khi thu từ cảnh`);
  stSceneStats.buildings = nb; stSceneStats.footprints = nf; stSceneStats.skipped = bad;
  stAddSolids(map, out);
  return out.length;
}
